"""Writes src/py_unicode.rs: the code points Python's `re` takes as `\\w` and `\\d` in a `str` pattern, read
from the running CPython itself, so the Rust patterns follow CPython's Unicode tables (15.1 in 3.13) and
not the newer ones the `regex` crate ships. Run from the repository root with the daemon's Python:

    bridge/.venv/bin/python -I rust/crates/eve-telegram-format/tests/fixtures/gen_unicode.py
"""
from __future__ import annotations

import re
import sys
import unicodedata
from pathlib import Path

OUT = Path(__file__).resolve().parents[2] / "src" / "py_unicode.rs"


def ranges(pattern: str) -> list[tuple[int, int]]:
    rx = re.compile(pattern)
    out: list[tuple[int, int]] = []
    start = None
    for c in range(0x110001):
        hit = c < 0x110000 and rx.match(chr(c)) is not None
        if hit and start is None:
            start = c
        elif not hit and start is not None:
            out.append((start, c - 1))
            start = None
    return out


def klass(rs: list[tuple[int, int]]) -> str:
    return "".join(f"\\x{{{a:X}}}" if a == b else f"\\x{{{a:X}}}-\\x{{{b:X}}}" for a, b in rs)


def main() -> None:
    word, digit = ranges(r"\w"), ranges(r"\d")
    OUT.write_text(
        "//! Python's `\\w` and `\\d` in a `str` pattern, as the inside of a regex character class. Generated by\n"
        f"//! `tests/fixtures/gen_unicode.py` from CPython {sys.version.split()[0]} (Unicode "
        f"{unicodedata.unidata_version}); do not edit.\n"
        "//! The `regex` crate's `\\p{L}`, `\\p{N}` and `\\d` follow a newer Unicode, where letters and digits\n"
        "//! Python does not know yet would count.\n\n"
        f"/// `\\w`: {len(word)} ranges.\n"
        f'pub(crate) const WORD: &str = r"{klass(word)}";\n\n'
        f"/// `\\d`: {len(digit)} ranges.\n"
        f'pub(crate) const DIGIT: &str = r"{klass(digit)}";\n'
    )
    print(OUT, len(word), len(digit))


if __name__ == "__main__":
    main()
